// #03f662e4191d3e3c2a3382fd — на /candidates при 1440 (и 1280) таблица кандидатов внутри панели,
// у страницы нет горизонтальной прокрутки, все действия строки видимы и кликабельны. Кейс CAND-003.
// Только чтение — @prod-safe.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const VIEWPORTS = [
  { width: 1440, height: 900 },
  { width: 1280, height: 900 },
];

/** Документ, таблица, её панель (ближайший предок с фоном/рамкой/скруглением) и обёртки между ними. */
async function measureLayout(page: Page) {
  return page.evaluate(() => {
    const de = document.documentElement;
    const table = document.querySelector('main table') as HTMLElement;
    const tr = table.getBoundingClientRect();
    const isPanel = (el: Element) => {
      const cs = getComputedStyle(el);
      const bg = cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent';
      return bg || parseFloat(cs.borderTopWidth) > 0 || parseFloat(cs.borderTopLeftRadius) > 0 || cs.backdropFilter !== 'none';
    };
    const scrollers: string[] = [];
    let panel: Element | null = null;
    for (let el: Element | null = table; el && el.tagName !== 'MAIN'; el = el.parentElement) {
      const h = el as HTMLElement;
      if (h.scrollWidth > h.clientWidth + 1) scrollers.push(`${el.tagName}.${String(h.className).slice(0, 40)} ${h.scrollWidth}>${h.clientWidth}`);
      if (el !== table && !panel && isPanel(el)) panel = el;
    }
    const pr = (panel || table.parentElement!).getBoundingClientRect();
    return {
      vw: window.innerWidth,
      docScrollWidth: de.scrollWidth,
      docClientWidth: de.clientWidth,
      table: { left: tr.left, right: tr.right },
      panel: { left: pr.left, right: pr.right },
      scrollers,
      rows: table.querySelectorAll('tbody tr').length,
    };
  });
}

test.describe('Кандидаты — таблица помещается в панель (#03f662e4191d3e3c2a3382fd)', () => {
  for (const viewport of VIEWPORTS) {
    test(`ширина ${viewport.width}: таблица внутри панели, scrollWidth == clientWidth, действия строки в viewport и кликабельны @desktop @prod-safe #03f662e4191d3e3c2a3382fd`, async ({ asUser }) => {
      const page = await asUser('business');
      await page.setViewportSize(viewport);
      await page.goto('/candidates');
      await expect(page.getByRole('heading', { level: 1, name: 'מועמדים' })).toBeVisible();
      const rows = page.locator('main table tbody tr');
      await expect(rows.first(), 'в списке нет строк кандидатов — нужны реальные данные').toBeVisible();

      // Источник: AC — «טבלת המועמדים מוצגת בתוך הפאנל בלי גלילה אופקית של העמוד».
      const m = await measureLayout(page);
      expect(m.docScrollWidth, 'горизонтальная прокрутка страницы').toBe(m.docClientWidth);
      expect(m.scrollers, 'таблица/обёртки прокручиваются по горизонтали').toEqual([]);
      expect(m.table.left).toBeGreaterThanOrEqual(m.panel.left - 1);
      expect(m.table.right).toBeLessThanOrEqual(m.panel.right + 1);
      expect(m.table.right).toBeLessThanOrEqual(m.vw);

      // Источник: AC — «כל פעולות השורה גלויות» (в макете 678:652 действия появляются при наведении).
      const problems: string[] = [];
      const count = await rows.count();
      for (let i = 0; i < count; i++) {
        const row = rows.nth(i);
        await row.scrollIntoViewIfNeeded();
        await row.hover();
        const res = await row.evaluate((tr) => {
          const out: string[] = [];
          const items = [...tr.querySelectorAll('button, a[href]')] as HTMLElement[];
          let checked = 0;
          for (const b of items) {
            const r = b.getBoundingClientRect();
            const cs = getComputedStyle(b);
            if (r.width === 0 || r.height === 0 || cs.visibility === 'hidden' || cs.display === 'none') continue;
            checked++;
            const name = (b.getAttribute('aria-label') || b.innerText || b.tagName).trim().slice(0, 40);
            if (r.left < 0 || r.right > window.innerWidth || r.top < 0 || r.bottom > window.innerHeight) {
              out.push(`«${name}» вне viewport [${Math.round(r.left)}..${Math.round(r.right)}]`);
              continue;
            }
            const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
            if (!hit || !(hit === b || b.contains(hit))) out.push(`«${name}» перекрыт/обрезан (в центре ${hit?.tagName})`);
          }
          return { out, checked };
        });
        if (!res.checked) problems.push(`строка ${i + 1}: после наведения нет видимых действий`);
        res.out.forEach((p) => problems.push(`строка ${i + 1}: ${p}`));
      }
      expect(problems).toEqual([]);
    });
  }
});
